modules.registry=(function()
-- Dependency-injected publication core. No game discovery, native calls or
-- Windows API here. The adapter must validate exact build, slot ownership,
-- pointed record bytes, allocation lifetime and resource epoch before use.
local M={}
local function read(api,address,size)
    local result=api.read(address,size)
    assert(type(result)=='string' and #result==size,'Registry read failed')
    return result
end
local function validate(api,plan)
    assert(plan.approved==true,'Registry slot ownership is not approved')
    assert(type(plan.epoch)=='string' and #plan.epoch>0,'Missing registry resource epoch')
    assert(api.epoch()==plan.epoch,'Registry resource epoch changed')
    assert(#plan.slots==3 or #plan.slots==4 or #plan.slots==6 or #plan.slots==7,'Unexpected registry publication plan')
    local kinds=#plan.slots==7 and {'explosion','damage','damage','explosion','explosion','projectile','projectile'}
      or (#plan.slots==6 and {'explosion','damage','damage','explosion','explosion','projectile'}
      or (#plan.slots==4 and {'damage','damage','explosion','projectile'} or {'damage','explosion','projectile'})
      )
    local keys={}
    for i,slot in ipairs(plan.slots) do
        assert(slot.kind==kinds[i],'Registry dependency order changed')
        assert(type(slot.before)=='string' and #slot.before==8
            and type(slot.after)=='string' and #slot.after==8,'Invalid registry pointer bytes')
        assert(slot.before~=slot.after,'Replacement must have separate owned storage')
        assert(slot.pin~=nil,'Replacement allocation is not retained')
        assert(type(slot.original_record)=='string' and type(slot.replacement_record)=='string'
            and #slot.original_record==#slot.replacement_record,'Invalid registry record')
        local size=({damage=76,explosion=152,projectile=272})[slot.kind]
        assert(#slot.original_record==size,'Registry record size changed')
        local key=api.identity(slot.address)
        assert(not keys[key],'Overlapping registry slots');keys[key]=true
        assert(api.slot_allowed(slot.kind,slot.id,slot.address),'Unapproved registry address')
        assert(read(api,slot.original_address,size)==slot.original_record,'Original registry record changed')
        assert(read(api,slot.replacement_address,size)==slot.replacement_record,'Replacement record changed')
        assert(api.pointer_bytes(slot.original_address)==slot.before
            and api.pointer_bytes(slot.replacement_address)==slot.after,'Registry pointer encoding mismatch')
        assert(read(api,slot.address,8)==slot.before,'Registry slot was changed externally')
    end
    assert(api.epoch()==plan.epoch,'Registry resource epoch changed during validation')
end

function M.publish(api,plan)
    validate(api,plan)
    local state={epoch=plan.epoch,slots=plan.slots,pins={},active=false,poisoned=false}
    -- Pin first and retain even on failure: a partially published pointer must
    -- never outlive its allocation. Adapter retain is process-lifetime storage.
    for i,slot in ipairs(plan.slots) do state.pins[i]=slot.pin end
    api.retain(state)
    local attempted={}
    local ok,reason=pcall(function()
        for _,slot in ipairs(plan.slots) do
            assert(api.epoch()==plan.epoch,'Resource epoch changed before publication')
            assert(read(api,slot.address,8)==slot.before,'Registry pointer changed before publication')
            attempted[#attempted+1]=slot -- write can partly succeed before failure
            assert(api.write_slot(slot.kind,slot.id,slot.address,slot.after),'Registry pointer write failed')
            assert(read(api,slot.address,8)==slot.after,'Registry pointer readback failed')
        end
        assert(api.epoch()==plan.epoch,'Resource epoch changed after publication')
    end)
    if not ok then
        local rollback=true
        -- A resource reload may destroy the old registry allocation. Never put
        -- stale pointers back into the new epoch, even to attempt rollback.
        if api.epoch()~=plan.epoch then rollback=false
        else
            for i=#attempted,1,-1 do
                local slot=attempted[i]
                local restored,success=pcall(function()
                    assert(api.epoch()==plan.epoch,'Epoch changed during rollback')
                    local now=read(api,slot.address,8)
                    assert(now==slot.after or now==slot.before,'Foreign registry edit prevents rollback')
                    if now~=slot.before then
                        assert(api.write_slot(slot.kind,slot.id,slot.address,slot.before),'Rollback write failed')
                    end
                    assert(read(api,slot.address,8)==slot.before,'Rollback readback failed')
                    return true
                end)
                if not restored or not success then rollback=false end
            end
        end
        state.poisoned=not rollback
        return nil,tostring(reason),state
    end
    state.active=true
    return state
end

function M.check(api,state)
    assert(state.active and not state.poisoned,'Registry publication is not active')
    assert(api.epoch()==state.epoch,'Registry resource epoch changed')
    for _,slot in ipairs(state.slots) do
        assert(read(api,slot.address,8)==slot.after,'Published registry pointer changed')
        assert(read(api,slot.replacement_address,#slot.replacement_record)==slot.replacement_record,
            'Published registry record changed')
    end
    return true
end
-- No automatic unpublish/free: in-flight projectiles may still hold pointers.
-- Native registry cleanup/reset must be handled by a separately verified epoch
-- adapter. Retained allocations remain alive for the process lifetime.
return M

end)()
modules.runtime=(function()
-- Donor publication + per-instance mode/spread orchestration.
-- Exact-build Windows/source/epoch adapters are separate dependencies.
local M={}
local sizes={damage=76,explosion=152,projectile=272}
local ids={damage=305,explosion=355,projectile=171}
local function read(api,p,n)
 local s=api.read(p,n);assert(type(s)=='string'and #s==n,'Donor data unreadable');return s
end
local function unchanged(api,state)
 assert(api.epoch()==state.epoch,'Donor resource epoch changed')
 for _,g in ipairs(state.protected)do assert(read(api,g.address,#g.bytes)==g.bytes,'Protected normal/Scorcher/source record changed')end
 assert(read(api,state.owned.shake_address,#state.owned.shake_bytes)==state.owned.shake_bytes,'Owned shake assets changed')
 for _,g in ipairs(state.owned.shakes or {})do assert(read(api,g.address,#g.bytes)==g.bytes,'Owned normal shake assets changed')end
 if state.config.tuning then
  local g=state.config.tuning_sources.equivalent_damage
  assert(read(api,g.slot,8)==api.pointer_bytes(g.address),'Equivalent damage315 registry slot changed')
 end
end
function M.start(api,c,modules)
 assert(c.route=='user-selected-loyalist-donor','Explicit donor policy missing')
 assert(type(c.protected)=='table','Protected records missing')
 local required={normal_projectile=true,normal_blast=true,normal_blast_damage=true,
  direct_impact=true,scorcher_projectile=true,scorcher_direct=true,
  scorcher_explosion=true,scorcher_blast=true,stock_magazine=true}
 if c.tuning then required.equivalent_damage=true end
 if c.blast_burning then required.burning_reference=true end
 for _,g in ipairs(c.protected)do
  assert(required[g.name]==true,'Unknown/duplicate protected guard')
  assert(type(g.bytes)=='string'and #g.bytes>0,'Empty protected guard')
  assert(read(api,g.address,#g.bytes)==g.bytes,'Protected source changed')
  required[g.name]=false
 end
 for name,pending in pairs(required)do assert(not pending,'Missing protected '..name)end
 assert(api.epoch()==c.epoch,'Donor epoch changed')
 local owned=modules.owned.build(api,c)
 local plan={epoch=c.epoch,approved=true,slots={}}
 for _,kind in ipairs({'damage','explosion','projectile'})do
  local original=assert(c.originals[kind]);assert(original.id==ids[kind],'Wrong donor original')
  assert(#original.bytes==sizes[kind],'Wrong donor record size')
  assert(read(api,original.address,sizes[kind])==original.bytes,'Donor source changed')
  assert(api.identity(original.slot)==api.identity(c.registry_slots[kind]),'Donor slot changed')
  plan.slots[#plan.slots+1]={kind=kind,id=ids[kind],address=original.slot,
    before=api.pointer_bytes(original.address),after=api.pointer_bytes(owned.addresses[kind]),
    original_address=original.address,original_record=original.bytes,
    replacement_address=owned.addresses[kind],replacement_record=owned.records[kind],pin=owned}
 end
 if c.tuning then
  local t=c.tuning_sources
  local function slot(kind,id,g,key)
   return {kind=kind,id=id,address=g.slot,before=api.pointer_bytes(g.address),
    after=api.pointer_bytes(owned.addresses[key]),original_address=g.address,original_record=g.bytes,
    replacement_address=owned.addresses[key],replacement_record=owned.records[key],pin=owned}
  end
  -- Preserve the alternate consumer before publishing the stronger normal311.
  local donor=plan.slots
  plan.slots={slot('explosion',377,t.alternate_explosion,'alternate_explosion'),
   slot('damage',311,t.normal_damage,'normal_damage'),donor[1],
   slot('explosion',290,t.normal_explosion,'normal_explosion'),donor[2],donor[3]}
  if c.normal_flight then
   plan.slots[#plan.slots+1]=slot('projectile',57,c.normal_projectile,'normal_projectile')
  end
 end
 local state={epoch=c.epoch,owned=owned,protected=c.protected,config=c,active=false,poisoned=false}
 unchanged(api,state)
 local registry,reason,failure=modules.registry.publish(api,plan)
 state.registry=registry or failure
 if not registry then state.poisoned=failure and failure.poisoned or false;return nil,reason,state end
 owned.published=true;state.active=true
 if c.magazine_tuning then
  local magazine,why,poisoned=assert(modules.magazine,'Magazine module missing').apply(api,c,function()return modules.registry.check(api,state.registry)end)
  if not magazine then state.active=false;state.poisoned=poisoned;return nil,why,state end
  state.magazine=magazine
 end
 return state
end
function M.tick(api,state,modules)
 assert(state.active and not state.poisoned,'Donor runtime inactive')
 local ok,result=pcall(function()
  unchanged(api,state);modules.registry.check(api,state.registry)
  local config=state.config.snapshot
  assert(config.shotgun_id==171 and config.epoch==state.epoch,'Snapshot donor policy changed')
  local snapshot=modules.snapshot.collect(api,modules.modes,config)
  local old=api.validate_snapshot
  api.validate_snapshot=function()
   local valid=pcall(unchanged,api,state)
   return valid and snapshot.validate() and modules.registry.check(api,state.registry)
  end
  local outcome={pcall(function()
   return modules.cache.commit(api,modules.cache.plan(api,state.epoch,snapshot.groups,snapshot.extra))
  end)}
  api.validate_snapshot=old
  assert(outcome[1],outcome[2])
  if not outcome[2]then
   if outcome[4]and outcome[4].poisoned then state.poisoned=true end
   error(outcome[3])
  end
  if config.fast_watch then state.watch=modules.snapshot.watch(api,config,snapshot)end
  return {instances=#snapshot.instances,writes=outcome[3],mode_observations=snapshot.instances}
 end)
 if not ok then state.active=false;state.error=tostring(result);return nil,state.error end
 return result
end
-- No automatic free/unpublish; projectiles can outlive weapon selection.
return M

end)()
modules.modes=(function()
-- Constructs private component bytes, without reading/writing the game. Native
-- cache registration and derived-state transactions belong to the adapter.
local ffi=require('ffi')
local M={}
local function word(value)
    local box=ffi.new('uint32_t[1]',value);return ffi.string(box,4)
end
local function float(value)
    local box=ffi.new('float[1]',value);return ffi.string(box,4)
end
local function replace(raw,offset,bytes)
    assert(offset>=0 and offset+#bytes<=#raw,'Profile edit exceeds component')
    return raw:sub(1,offset)..bytes..raw:sub(offset+#bytes+1)
end
local function u32(raw,offset)
    local box=ffi.new('uint32_t[1]');ffi.copy(box,raw:sub(offset+1,offset+4),4)
    return tonumber(box[0])
end
function M.build(stock,mode,shotgun_id,stage,sway_factor,normal_two_shot,normal_single_fast)
    stage=stage or 'firemode-and-pellets'
    assert(stage=='firemode-and-pellets' or stage=='full-design' or stage=='tuning-v017' or stage=='tuning-v014','Unsupported test stage')
    assert(mode==2 or mode==3,'Unsupported Punisher mode')
    assert(shotgun_id>=1 and shotgun_id<=350 and shotgun_id~=57
        and shotgun_id==math.floor(shotgun_id),'Invalid isolated shotgun projectile ID')
    assert(#stock.weapon==1232 and #stock.projectile==616 and #stock.magazine==160,'Unsupported component sizes')
    assert(u32(stock.projectile,0)==57 and stock.projectile:sub(9,12)==float(80),'Unexpected Punisher projectile source')
    assert(stock.weapon:sub(85,92)==float(8)..float(8),'Unexpected stock spread')
    assert(u32(stock.magazine,136)==10 and u32(stock.magazine,148)==8,'Unexpected magazine source')
    local weapon,projectile,magazine=stock.weapon,stock.projectile,stock.magazine
    if sway_factor then
        assert(sway_factor==0.5,'Unexpected sway tuning')
        local box=ffi.new('float[1]');ffi.copy(box,stock.weapon:sub(105,108),4)
        assert(box[0]>=0 and box[0]<=100,'Unsupported stock sway')
        weapon=replace(weapon,104,float(tonumber(box[0])*sway_factor))
    end
    local spread=mode==2 and 8 or 60
    local vertical=spread
    if stage=='tuning-v014'and mode==3 then spread=100;vertical=90 end
    weapon=replace(weapon,84,float(spread)..float(vertical))
    -- Native Burst is the second selector enum, but one firing event per pull
    -- is essential. Nine pellets belong to ProjectileInfo, never nine rounds.
    weapon=replace(weapon,140,word(1))
    weapon=replace(weapon,144,word(2)..word(3)..word(0)..word(0))
    if normal_two_shot then
        assert(stage=='tuning-v014','Two-shot normal requires current tuning')
        -- Semantic profile2 is normal, profile3 is pellets. Native selectors
        -- are Burst3 for normal and Semi2 for pellets; no input simulation.
        weapon=replace(weapon,140,word(mode==2 and 2 or 1))
        weapon=replace(weapon,144,word(3)..word(2)..word(0)..word(0))
    end
    if normal_single_fast then
        assert(normal_two_shot and normal_single_fast==120,'Unexpected single-shot rate')
        weapon=replace(weapon,140,word(1))
    end
    weapon=replace(weapon,184,word(3)..word(0))
    projectile=replace(projectile,0,word(mode==2 and 57 or shotgun_id))
    if stage=='tuning-v017' and mode==3 then projectile=replace(projectile,8,float(100)) end
    if stage=='tuning-v014'then projectile=replace(projectile,8,float(mode==2 and 60 or 100))end
    if normal_single_fast and mode==2 then projectile=replace(projectile,8,float(120)) end
    -- Burst MIDI can schedule extra notes independently of physical pellets.
    -- Keep native Semi MIDI; use the Accelerator's ordinary-event approach in
    -- shotgun mode. Audibility still requires a Punisher gameplay test.
    if mode==3 then projectile=replace(projectile,237,string.char(0)) end
    if stage=='full-design' then
        magazine=replace(magazine,136,word(20))
        magazine=replace(magazine,148,word(6))
    end
    return {weapon=weapon,projectile=projectile,magazine=magazine,
        derived_spread=float(spread)..float(vertical),mode=mode,
        native_rounds_per_event=1,desired_rounds_per_event=stage=='full-design' and mode==2 and 2 or 1,
        stage=stage,
        pellets=mode==2 and 1 or 9,rpm=normal_single_fast and mode==2 and 120 or stage=='tuning-v014'and(mode==2 and 60 or 100)or(stage=='tuning-v017' and mode==3 and 100 or 80),
        gameplay_verified=false,registry_ownership_verified=false}
end
return M


end)()
modules.profile=(function()
-- Exact stock records -> pre-creation profiles. No native state edits.
local ffi=require('ffi')
local function word(v)local b=ffi.new('uint32_t[1]',v);return ffi.string(b,4)end
local function float(v)local b=ffi.new('float[1]',v);return ffi.string(b,4)end
local function change(s,o,v)return s:sub(1,o)..v..s:sub(o+#v+1)end
return function(rows,modes,stock,reload_template)
 local baseline=modes.build(stock,2,171,'tuning-v014',0.5,true,120)
 local pellet=modes.build(stock,3,171,'tuning-v014',0.5,true,120)
 local out={}
 for _,r in ipairs(rows)do
  local s=r.before
  if r.role=='parent_weapon' then
   s=baseline.weapon
   -- First three entries belong to the fire-mode menu. Native underbarrel
   -- selection is the separate fourth enum through function11.
   s=change(s,144,word(2)..word(0)..word(0)..word(8))
   -- Native function11 reads these parent-owned display fields for its two LEFT choices.
   s=change(s,160,string.char(0xa7,0x0d,0x93,0x91,0xc0,0xe4,0xd9,0x07,0xbb,0x6b,0x89,0x2f,0x96,0xb0,0x7b,0x06))
   s=change(s,176,word(0xf3222616)..word(0xff4b018d)) -- stock localized NORMAL / SHOTGUN
   s=change(s,184,word(11)..word(0)) -- preserve LEFT underbarrel dispatch; remove redundant right Semi
  elseif r.role=='parent_projectile' then s=change(baseline.projectile,8,float(60)) -- final normal cadence only
  elseif r.role=='parent_magazine' then s=change(s,136,word(17)..word(1)..word(1)..word(1)) -- capacity/start/refill/max:17 loaded + one spare17 magazine
  elseif r.role=='parent_customization' then
   assert(s:sub(17,24)==string.rep('\0',8),'Default customization slot occupied')
   s=change(s,16,word(1)..word(0xa051bf6b))
   s=change(s,192,string.char(0xf5,0x45,0x84,0xcd,0x21,0x73,0xcd,0x02))
   s=change(s,4852,word(2))
  elseif r.role=='child_weapon' then
   s=change(s,0,pellet.weapon:sub(1,60))
   s=change(s,84,float(100)..float(90));s=change(s,140,word(1))
   local b=ffi.new('float[1]');ffi.copy(b,s:sub(105,108),4)
   assert(b[0]>=0 and b[0]<=100,'Unexpected child sway');s=change(s,104,pellet.weapon:sub(105,108))
   s=change(s,132,pellet.weapon:sub(133,133))
  elseif r.role=='child_projectile' then
   -- Whole accepted pellet firing profile; donor unit/reload stay native.
   s=pellet.projectile
  elseif r.role=='child_rounds' then
   s=change(s,64,word(171));s=change(s,72,float(20))
   s=change(s,80,word(60)..word(60)..word(60));s=change(s,104,string.char(0))
  elseif r.role=='child_reload' then
   assert(type(reload_template)=='string' and #reload_template==80,'Missing exact reload template')
   -- Copy only known working multi-round underbarrel ability + normal/fast animation-event sequence.
   -- Preserve One-Two flags, duration, shared-deposit and VO.
   s=change(s,4,reload_template:sub(5,56))
   s=change(s,56,float(121/60)) -- coupled native animation/timeline speed2x
  else error('Unknown source target')end
  assert(#s==#r.before and #s%4==0,'Source record size changed')
  out[#out+1]={role=r.role,before=r.before,after=s,owner=r.owner,offset=r.offset,
   count=r.count,index=r.index,stride=r.stride}
 end
 assert(#out==8,'Incomplete source profile')
 return out
end

end)()
modules.plan=(function()
-- Discover current source storage and prove target entities absent BEFORE
-- installing profiles. No retained live cache pointers or native game calls.
return function(api,game,c,D,profiles)
 local guards,rows={},{}
 local function get(p,n)local s=api.read(p,n);assert(type(s)=='string' and #s==n,'Source data unavailable');return s end
 local function u32(s,o)local a,b,c,d=s:byte(o+1,o+4);assert(d,'Short plan word');return a+b*256+c*65536+d*16777216 end
 local function ptr(p)return assert(api.pointer(get(p,8),0),'Source pointer unavailable')end
 local function guard(p,s)for o=0,#s-1,4096 do guards[#guards+1]={address=p+o,bytes=s:sub(o+1,o+4096)}end end
 local root=ptr(game+0x346bf98);guard(game+0x346bf98,get(game+0x346bf98,8))
 -- Include the same resource-owner anchors used by prepare's epoch closure
 -- in the NATIVE paused guard set, not only the preceding Lua check.
 for _,rva in ipairs({0x348e2f8,0x348e1f8,0x348ec88})do
  local s=get(game+rva,8);assert(api.pointer(s,0),'Resource owner unavailable');guard(game+rva,s)
 end
 local countbytes=get(root+0xf12470,4);local count=u32(countbytes,0);assert(count>0 and count<=128,'Source ledger count')
 local buffers=get(root+0xf11c70,count*8);local sizes=get(root+0xf12070,count*4)
 guard(root+0xf12470,countbytes);guard(root+0xf11c70,buffers);guard(root+0xf12070,sizes);guard(root+0xf12270,get(root+0xf12270,count*4))
 local emptybytes=get(game+0x348456c,4);guard(game+0x348456c,emptybytes);local empty=u32(emptybytes,0)
 for offset=0,2047,170 do
  local n=math.min(170,2048-offset);local bytes=get(root+0xf32f18+offset*24,n*24)
  guard(root+0xf32f18+offset*24,bytes)
  for i=0,n-1 do
   local row=bytes:sub(i*24+1,i*24+24)
   if u32(row,8)~=empty then
    local owner=row:sub(1,8)
    assert(owner~=D.owner and owner~=D.child_owner and owner~=D.one_two_owner,
     'Target weapon already exists; restart with another primary equipped')
   end
  end
 end
 for _,r in ipairs(profiles)do
  local slot=root+r.offset;local map=ptr(slot);guard(slot,get(slot,8))
  local mapping=get(map,r.count*16);local found,owners=0,0
  for i=0,r.count-1 do
   local owner=mapping:sub(i*16+1,i*16+8);local index=u32(mapping,i*16+8)
   if owner==r.owner then assert(index==r.index,'Source index changed');found=found+1 end
   if index==r.index and owner~=string.rep('\0',8) then owners=owners+1 end
  end
  assert(found==1 and owners==1,'Shared/ambiguous source target')
  local p=map+r.count*16+r.index*r.stride;assert(api.identity(p)%4==0,'Source alignment')
  local id=api.identity(p);local owned=false
  for i=0,count-1 do
   local b=api.pointer(buffers,i*8);local size=u32(sizes,i*4)
   assert(b and size>0 and size<=67108864,'Invalid source ledger buffer')
   local first=api.identity(b)
   if id>=first and id+#r.before<=first+size then owned=true end
